<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;
class Report extends Model{protected $fillable=['project_profile_id','survey_id','comparison_run_id','created_by','title','report_type','status','period_start','period_end','filters','data_sources','limitations','snapshot','methodology_version','generated_at'];protected function casts():array{return ['period_start'=>'datetime','period_end'=>'datetime','filters'=>'array','data_sources'=>'array','limitations'=>'array','snapshot'=>'array','generated_at'=>'datetime'];}public function survey(){return $this->belongsTo(Survey::class);}public function comparison(){return $this->belongsTo(ComparisonRun::class,'comparison_run_id');}public function profile(){return $this->belongsTo(ProjectProfile::class,'project_profile_id');}public function creator(){return $this->belongsTo(User::class,'created_by');}public function exports(){return $this->hasMany(ReportExport::class);}}
